//#region src/github-event/pull-request-review.ts
async function pull_request_review(token) {
	if (context.eventName !== "pull_request_review") return false;
	if (context.payload.action !== "submitted") return false;
	if (context.payload.review?.state !== "approved") return false;
	if (!(await getPrCommentWhitelist()).includes(context.actor)) return false;
	const prNumber = getPullRequestNumber();
	const pullRequestData = context.payload.pull_request;
	return confirmPullRequestChangelog(prNumber, pullRequestData, token);
}
//#endregion
//#region src/github-event/workflow-run.ts
async function workflow_run(token) {
	if (context.eventName !== "workflow_run") return false;
	if (context.payload.workflow_run?.event !== "pull_request_review") {
		warning(`github.context.payload.workflow_run?.event !== 'pull_request_review'`);
		return false;
	}
	if (context.payload.workflow_run?.status !== "completed") {
		warning(`github.context.payload.workflow_run?.status !== 'completed'`);
		return false;
	}
	if (context.payload.workflow_run?.conclusion !== "success") {
		warning(`github.context.payload.workflow_run?.conclusion !== 'success'`);
		return false;
	}
	const prNumber = Number(getInput("pr_number", { required: true }));
	if (!(await getPrCommentWhitelist()).includes(context.actor)) {
		warning(`no in whitelist:${context.actor}`);
		return false;
	}
	const { getPullRequestData } = useGithub(token);
	const pullRequestData = await getPullRequestData(prNumber);
	if (pullRequestData.head.ref.startsWith("release/")) return false;
	let logs = "";
	const prLog = extractChangelog(pullRequestData.body || "", getInputPkgs());
	info(`pr_log: ${JSON.stringify(prLog, null, 2)}`);
	Object.keys(prLog).forEach((pkgName) => {
		if (!prLog[pkgName].length) return;
		logs += `#### ${pkgName}\n`;
		prLog[pkgName].forEach((log) => {
			logs += `- ${log}\n`;
		});
	});
	if (logs) {
		const body = `### 📝 更新日志\n\n${logs}\n\n`;
		unlinkSync("./pr-id.txt");
		await confirmChangelog(prNumber, body, token);
	}
}
